// === Tab: mySketch ===
let t = 0;
let angleY = 0;
let rows = 96;
let cols = 256;
let radius = 300;

function setup() {
  createCanvas(800, 800, WEBGL);
  frameRate(60);
  smooth(0);
  noCursor();
  background(0);
}

function draw() {
  background(0);
  translate(width / 2, height / 2);

  // let rigidamente orbitale
  rotateX(HALF_PI);
  rotateZ(radians(-20));
  rotateY(angleY);

  stroke(255);
  strokeWeight(0.5);

  let bandFreq = 10.0;
  let flickerSpeed = 0.5;
  let flickerFreq = 12.0;

  for (i = 0; i < rows; i++) {
    let phi = map(i, 0, rows - 1, -HALF_PI, HALF_PI);
    let y = radius * sin(phi);
    let r = radius * cos(phi);

    for (j = 0; j < cols; j++) {
      let theta = map(j, 0, cols, 0, TWO_PI);
      let x = r * cos(theta);
      let z = r * sin(theta);

      // modulo binario rigido: ON/let float flick = sin(t * flickerSpeed + i * 0.1 + j * 0.2);
      let band = sin(theta * bandFreq + i * 0.05 + t);

      // vincolo: solo se entrambi sopra soglia
      if (flick > 0.8 && band > 0.1) {
        line(x - 1, y, z, x + 1, y, z);
      }
    }
  }

  angleY += 0.001;  // movimento lentissimo
  t += 0.02;        // clock costante
}

